package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func probe(routes []string, reqs []string) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	for _, rt := range routes {
		p := rt
		r.GET(p, func(c *gin.Context) {
			c.String(200, "path=%s params=%v", c.FullPath(), c.Params)
		})
	}
	for _, q := range reqs {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, q, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("  req=%-24q -> %d %s\n", q, w.Code, w.Body.String())
	}
}

func main() {
	fmt.Println("== params-not-empty style ==")
	probe([]string{"/test/:param", "/test/:param/test", "/test/:param/test/:param2"},
		[]string{"/test/foo", "/test/foo/test", "/test/foo/test/bar", "/test/foo/test/bar/baz"})
	fmt.Println("== with static sibling ==")
	probe([]string{"/test/:param", "/test/static"},
		[]string{"/test/foo", "/test/static", "/test/static/x"})
	fmt.Println("== param + catchall ==")
	probe([]string{"/test/:param", "/test/:param/*action"},
		[]string{"/test/foo", "/test/foo/bar", "/test/foo/bar/baz"})
	fmt.Println("== deeper mixed ==")
	probe([]string{"/test/:param/test", "/test/static/test"},
		[]string{"/test/foo/test", "/test/static/test"})
}
EOF
