func TestZZTmpValueUnwrap(t *testing.T) {
	innerErr := TestErr("some error")

	// gin.Error used as a VALUE (this is what the documented contract covers)
	err := fmt.Errorf("wrapped: %w", Error{Err: innerErr, Type: ErrorTypeAny})
	if !errors.Is(err, innerErr) {
		t.Fatalf("errors.Is failed for gin.Error value")
	}
	var testErr TestErr
	if !errors.As(err, &testErr) {
		t.Fatalf("errors.As failed for gin.Error value")
	}
	if got := errors.Unwrap(Error{Err: innerErr}); got != innerErr {
		t.Fatalf("errors.Unwrap failed for gin.Error value: %v", got)
	}
	// pointer form must keep working too
	perr := fmt.Errorf("wrapped: %w", &Error{Err: innerErr, Type: ErrorTypeAny})
	if !errors.Is(perr, innerErr) {
		t.Fatalf("errors.Is failed for *gin.Error")
	}
	var pe *Error
	if !errors.As(perr, &pe) || pe.Err != innerErr {
		t.Fatalf("errors.As failed for *gin.Error")
	}
}
